-- Per-category US ESTIMATES for all 4,041 categories (generation pass, entity-type-aware)
-- estimated_profiles=individual practitioners w/ public identity (0 for pure-location categories)
-- estimated_locations=US establishments; us_relevance=high|medium|low|none; idempotent.

ALTER TABLE gbp_categories
  ADD COLUMN IF NOT EXISTS estimated_profiles   BIGINT,
  ADD COLUMN IF NOT EXISTS estimated_locations  BIGINT,
  ADD COLUMN IF NOT EXISTS us_relevance         TEXT,
  ADD COLUMN IF NOT EXISTS estimate_confidence  TEXT,
  ADD COLUMN IF NOT EXISTS estimate_source      TEXT,
  ADD COLUMN IF NOT EXISTS estimate_updated_at  TIMESTAMPTZ;

UPDATE gbp_categories AS g SET
  estimated_profiles  = v.p, estimated_locations = v.l,
  us_relevance = v.r, estimate_confidence = v.c,
  estimate_source = 'generated', estimate_updated_at = NOW()
